import { JsonAsset } from 'cc';
import type { StoryChoiceScript, StoryDialogueScript, StoryMapJson, StoryNpcDef, StoryNpcEvent, StoryRequirement } from './StoryMapTypes';
import type { StoryLocalTaskState } from './StoryLocalTaskState';

/**
 * 解析地图 JsonAsset，提供 NPC / 脚本索引与事件筛选。
 */
export class StoryMapModel {
    readonly raw: StoryMapJson;
    readonly npcsByUid = new Map<string, StoryNpcDef>();
    readonly dialogueScripts = new Map<string, StoryDialogueScript>();
    readonly choiceScripts = new Map<string, StoryChoiceScript>();
    readonly maxInteractDistance: number;

    constructor(jsonAsset: JsonAsset | null) {
        const raw = (jsonAsset?.json ?? {}) as StoryMapJson;
        this.raw = raw;
        this.maxInteractDistance = raw.server?.antiCheat?.maxInteractDistance ?? 120;

        const npcs = raw.npcs ?? [];
        for (let i = 0; i < npcs.length; i++) {
            const n = npcs[i];
            if (n?.npcUid) this.npcsByUid.set(n.npcUid, n);
        }

        const dc = raw.client?.dialogueScripts ?? {};
        Object.keys(dc).forEach((k) => this.dialogueScripts.set(k, dc[k]));

        const cc = raw.client?.choiceScripts ?? {};
        Object.keys(cc).forEach((k) => this.choiceScripts.set(k, cc[k]));
    }

    requirementsMet(reqs: StoryRequirement[], state: StoryLocalTaskState): boolean {
        for (let i = 0; i < reqs.length; i++) {
            const r = reqs[i];
            const tid = r.taskId;
            if (tid === undefined) continue;
            if (r.type === 'task_accepted') {
                if (!state.isTaskAccepted(tid)) return false;
            } else if (r.type === 'task_completed') {
                if (!state.isTaskCompleted(tid)) return false;
            }
        }
        return true;
    }

    /**
     * 按 order 取第一条：未完成 + 满足 requirements。
     */
    getFirstEligibleEvent(npcUid: string, state: StoryLocalTaskState): StoryNpcEvent | null {
        const npc = this.npcsByUid.get(npcUid);
        if (!npc?.events?.length) return null;
        const sorted = [...npc.events].sort((a, b) => a.order - b.order);
        for (let i = 0; i < sorted.length; i++) {
            const ev = sorted[i];
            if (state.isEventCompleted(ev.eventId)) continue;
            if (!this.requirementsMet(ev.server?.requirements ?? [], state)) continue;
            return ev;
        }
        return null;
    }

    getDialogue(id: string | undefined): StoryDialogueScript | null {
        if (!id) return null;
        return this.dialogueScripts.get(id) ?? null;
    }

    getChoice(id: string | undefined): StoryChoiceScript | null {
        if (!id) return null;
        return this.choiceScripts.get(id) ?? null;
    }
}
